const form=document.querySelector('#booking-form');const day=document.querySelector('#day');const d=new Date();day.min=[d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-');document.querySelectorAll('[data-service]').forEach(a=>a.addEventListener('click',()=>{form.querySelectorAll('[name=service]').forEach(input=>input.checked=input.value===a.dataset.service)}));form.addEventListener('submit',e=>{e.preventDefault();if(!form.reportValidity())return;const service=new FormData(form).get('service');const date=day.value.split('-').reverse().join('/');const time=document.querySelector('#time').value;const note=document.querySelector('#note').value.trim();const text=`Olá, Taiane! Gostaria de marcar ${service.toLowerCase()}.\nDia pretendido: ${date}\nHorário pretendido: ${time}${note?'\n\n'+note:''}\n\nPode confirmar a disponibilidade e o valor, por favor?`;window.open('https://wa.me/351968733228?text='+encodeURIComponent(text),'_blank','noopener,noreferrer');});
